            u1, v1, w1 = mst_edges[i]
            u2, v2, w2 = mst_edges[j]

            temp_parent = parent.copy()
            temp_rank = rank.copy()
            temp_mst_edges = mst_edges.copy()
            temp_mst_set = mst_set.copy()
            temp_total_cost = total_cost

            new_w1 = w1 + 1
            new_w2 = w2 + 1
            temp_mst_edges[i] = (u1, v1, new_w1)
            temp_mst_edges[j] = (u2, v2, new_w2)
            temp_mst_edges.sort(key=lambda x: x[2])

            temp_parent = [i for i in range(n+1)]
            temp_rank = [0]*(n+1)

            def temp_find(u):
                while temp_parent[u] != u:
                    temp_parent[u] = temp_parent[temp_parent[u]]
                    u = temp_parent[u]
                return u

            def temp_union(u, v):
                u_root = temp_find(u)
                v_root = temp_find(v)
                if u_root == v_root:
                    return False
                if temp_rank[u_root] > temp_rank[v_root]:
                    temp_parent[v_root] = u_root
                else:
                    temp_parent[u_root] = v_root
                    if temp_rank[u_root] == temp_rank[v_root]:
                        temp_rank[v_root] += 1
                return True

            temp_mst = []
            temp_cost = 0
            for eu, ev, ew in temp_mst_edges:
                if temp_union(eu, ev):
                    temp_mst.append((eu, ev, ew))
                    temp_cost += ew

            if temp_cost == total_cost and len(temp_mst) == n-1:
